package com.magicstudios.magiccore.modules.tools;
import java.util.*;
public final class ToolAreaPlanner{public enum Face{UP,DOWN,NORTH,SOUTH,EAST,WEST}public List<ToolBlockPosition>plan(ToolBlockPosition origin,Face face,ToolUpgrade upgrade){LinkedHashSet<ToolBlockPosition>result=new LinkedHashSet<>();int r=upgrade.radius(),depth=upgrade.shape()==ToolUpgrade.Shape.PLANE?1:upgrade.depth();for(int d=0;d<depth;d++)for(int a=-r;a<=r;a++)for(int b=-r;b<=r;b++){int x=origin.x(),y=origin.y(),z=origin.z();switch(face){case UP->{x+=a;y-=d;z+=b;}case DOWN->{x+=a;y+=d;z+=b;}case NORTH->{x+=a;y+=b;z+=d;}case SOUTH->{x+=a;y+=b;z-=d;}case EAST->{x-=d;y+=b;z+=a;}case WEST->{x+=d;y+=b;z+=a;}}result.add(new ToolBlockPosition(x,y,z));}if(result.size()>256)throw new IllegalArgumentException("Tool area exceeds 256 blocks");return List.copyOf(result);}}
